import type {
  ActionType,
  Column,
  Hooks,
  TableInstance,
  TableState,
} from 'react-table';
import { actions } from 'react-table';

import { useColumnsSizesActions } from './actions.js';
import {
  createColumnGridTemplate,
  prepareColumnsForRemeasuring,
} from './column-size-utils.js';
import {
  getCellProps,
  getHeaderGroupProps,
  getHeaderProps,
  getLastVisibleStandardColumn,
  getRowProps,
  getTableProps,
} from './prop-getters.js';
import { DATA_TABLE_SUB_ROW_TRIGGER_ID } from '../../DataTable/constants.js';

// Table typings are still based on community types which are not that great,
// need to disable no-explicit-any for the plugin file.
/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/ban-types*/

/** State reducer for the useColumnSizes plugin. Takes care of column layouting and resizing. */
function reducer(
  state: TableState,
  action: ActionType,
  previousState?: TableState,
  instance?: TableInstance,
) {
  if (action.type === actions.init) {
    return {
      ...state,
      columnGridTemplate: undefined,
      columWidthMeasureMap: undefined,
      isMeasuringInProgress: false,
    };
  }

  if (!instance || instance.visibleColumns.length === 0) {
    return state;
  }

  // check in all columns
  const hasAutoWidthsDefined = !!instance.visibleColumns.find(
    (column) => column.autoWidth === true,
  );
  const hasRatioWidthsDefined = !!instance.visibleColumns.find(
    (column) => column.ratioWidth !== undefined,
  );
  const lastHeaderId = getLastVisibleStandardColumn(
    instance.visibleColumns,
  )?.id;
  const resizingEnabled = !instance.disableResizing;

  if (resizingEnabled && hasRatioWidthsDefined) {
    // eslint-disable-next-line no-console
    console.warn(
      'DataTable: resizable is currently not supported in combination with ratioWidth on column definitions, ignoring resizable.',
    );
  }

  // when resizing a table with autoWidth columns we have to switch from grid template to flex layout,
  // therefore we need to remove the grid template
  if (
    action.type === useColumnsSizesActions.columnStartResizing &&
    hasAutoWidthsDefined
  ) {
    return {
      ...state,
      columnGridTemplate: undefined,
      cellWidthsByColumn: undefined,
    };
  }

  // remove resized column widths for columns that are no longer in the column definition
  if (
    action.type === useColumnsSizesActions.updateResizedColumnWidths &&
    state.columnResizing.columnWidths
  ) {
    const currentColumnIds: string[] = action.currentColumnIds;
    Object.keys(state.columnResizing.columnWidths).forEach(
      (columnId) =>
        !currentColumnIds.includes(columnId) &&
        delete state.columnResizing.columnWidths[columnId],
    );
    return state;
  }

  if (
    action.type === useColumnsSizesActions.visibleColumnsChanged &&
    !state.columnResizing.isResizingColumn
  ) {
    // clear any previous grid templates if they exist
    delete state.columnGridTemplate;
    action.deleteSavedAutoWidths && delete state.cellWidthsByColumn;

    // if there are no autoWidth/ratioWidth columns, use flex layout
    if (!hasAutoWidthsDefined && !hasRatioWidthsDefined) {
      return state;
    }

    // Create the initial grid template string with autoWidth columns set to max-content to enable measuring
    // do this only once the column definition changes or a custom column was updated to not run the collection
    // every time the props are being collected.
    const columnGridTemplate = createColumnGridTemplate(
      instance.visibleColumns,
      lastHeaderId,
      hasRatioWidthsDefined,
      state.cellWidthsByColumn,
      state.columnResizing.columnWidths,
    );

    return {
      ...state,
      columnGridTemplate,
      isMeasuringInProgress: true,
    };
  }

  // Recreate the grid template to remeasure autoWidths if the rowDensity changed
  if (
    (action.type === useColumnsSizesActions.rowDensityChanged ||
      action.type === useColumnsSizesActions.fontsFamiliesUpdated) &&
    hasAutoWidthsDefined
  ) {
    const { headersWithResetAutoWidth, isRemeasuringNeeded } =
      prepareColumnsForRemeasuring(state, instance.visibleColumns);

    if (isRemeasuringNeeded) {
      const columnGridTemplate = createColumnGridTemplate(
        headersWithResetAutoWidth,
        lastHeaderId,
        hasRatioWidthsDefined,
        {},
        state.columnResizing.columnWidths,
      );

      return {
        ...state,
        columnGridTemplate,
        cellWidthsByColumn: undefined,
        isMeasuringInProgress: true,
      };
    } else {
      return state;
    }
  }

  // Create the final grid template string after autoWidths were measured
  if (action.type === useColumnsSizesActions.cellWidthMeasureDone) {
    const columnGridTemplate = createColumnGridTemplate(
      instance.visibleColumns,
      lastHeaderId,
      hasRatioWidthsDefined,
      state.cellWidthsByColumn,
      state.columnResizing.columnWidths,
    );

    return {
      ...state,
      columnGridTemplate,
      isMeasuringInProgress: false, // avoids re-render issue which occurs in apps
    };
  }

  // when the sub rows depth changed, we need to update the grid template
  if (
    action.type === useColumnsSizesActions.subRowsDepthChanged &&
    state.columnGridTemplate
  ) {
    const gridTemplateArray = state.columnGridTemplate.split(' ');
    const subRowsColumnIndex = instance.visibleColumns.findIndex(
      (column) => column.id === DATA_TABLE_SUB_ROW_TRIGGER_ID,
    );
    gridTemplateArray[subRowsColumnIndex] = '0fr';

    return {
      ...state,
      columnGridTemplate: gridTemplateArray.join(' '),
    };
  }

  return state;
}

/**
 * Additional Columns hook, will add a default expander column to the memoed
 * column definition automatically.
 */
function validateColumnSizing<D extends {}>(columns: Column<D>[]): Column<D>[] {
  const newColumns = [...columns];

  for (const column of newColumns) {
    if ((column as any).autoWidth === true && (column as any).columns) {
      // eslint-disable-next-line no-console
      console.warn(
        'Parent columns cannot apply auto-sizing. Setting is ignored',
      );
      (column as any).autoWidth = undefined;
    }
  }

  return newColumns;
}

/**
 * When enabling block layout, the default width of a column will always be fixed
 * to the react-table column width. If the resizer is disabled, this is not the desired
 * behaviour and should behave like a default table.
 */
export function useColumnSizes(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  hooks: Hooks<any>,
): void {
  hooks.columns.push(validateColumnSizing);
  hooks.stateReducers.push(reducer);
  hooks.getTableProps.push(getTableProps);
  hooks.getRowProps.push(getRowProps);
  hooks.getHeaderGroupProps.push(getHeaderGroupProps);
  hooks.getHeaderProps.push(getHeaderProps);
  hooks.getCellProps.push(getCellProps);
}

useColumnSizes.pluginName = 'useColumnSizes';
